        if($op==='prepare'){
            if(\val($p,'trust')!=='INSTALL')throw new Failure('Enter INSTALL to authorize trusted WordPress code.');
            $file=Tools::uploaded($_FILES['wordpress']??[],47185920);$db=[];foreach(['db_host','db_name','db_user','db_password'] as $key)$db[$key]=\val($p,$key);Runtime::prepare($app,$file,$db);return;
        }
        if($op==='wrap'){
            if(\val($p,'trust')!=='INSTALL')throw new Failure('Enter INSTALL to authorize trusted module code.');
            $file=Tools::uploaded($_FILES['module']??[],67108864);Runtime::wrap($app,$file,\val($p,'kind'));return;
        }
