<?php if(!$cfg)return;?>
<section class="panel"><h2><?=\e(\t('Exécution et accueil','Execution and home page'))?></h2><?=self::start('settings')?><label class="checkbox"><input type="checkbox" name="enabled" <?=!empty($data['enabled'])?'checked':''?>><?=\e(\t('Activer le moteur préparé','Enable the prepared engine'))?></label><label class="checkbox"><input type="checkbox" name="home" <?=!empty($data['home'])?'checked':''?>><?=\e(\t('Rediriger l’accueil natif vers WordPress','Redirect native home to WordPress'))?></label><label class="checkbox"><input type="checkbox" name="compatibility" <?=!empty($data['compatibility'])?'checked':''?>><?=\e(\t('Compatibilité WordPress complète pour les thèmes et plugins de confiance (dont WooCommerce)','Full WordPress compatibility for trusted themes and plugins (including WooCommerce)'))?></label><p><?=\e(\t('Ce mode conserve les sessions, nonces, API REST et AJAX WordPress. Les extensions assurent leurs propres contrôles métier ; les interdictions natives de l’administration CMS restent appliquées.','This preserves WordPress sessions, nonces, REST and AJAX. Plugins enforce their own business checks; native CMS administration remains protected.'))?></p><?=self::password()?><button class="button primary"><?=\e(\t('Enregistrer','Save'))?></button></form></section>
<section class="panel"><h2><?=\e(\t('Accès propriétaire temporaire','Temporary owner access'))?></h2><p><?=\e(\t('Un ticket à usage unique initialise une base vide lors du premier accès. Les sessions du pont expirent après 30 minutes et sont révoquées à la modification du compte CMS.','A single-use ticket initializes an empty database on first access. Bridge sessions expire after 30 minutes and are revoked when the CMS account changes.'))?></p><?=self::start('open')?><select name="target"><?php foreach(['plugins','themes','health','export','dashboard'] as $target):?><option value="<?=$target?>"><?=$target?></option><?php endforeach;?></select><?=self::password()?><button class="button primary"><?=\e(\t('Ouvrir WordPress','Open WordPress'))?></button></form></section>
